powerpagecomponent.content:
{
  "source": "<div id="mainContent" class="wrapper-body" role="main">
    {% include 'Page Copy' %}
    <script>
        var targetNode = document.getElementById('mainContent');
        var observer = new MutationObserver(function(mutations) {
            mutations.forEach(function(mutation) {
                if (mutation.type === 'childList') {
                    var detailLinks = document.querySelectorAll('.details-link');
                    detailLinks.forEach(function(link) {
                        // Perform the link update
                        updateLinkHref(link);
                    });
                    // Query for all candidate name links with the specific entityformid
                    var candidateNameLinks = document.querySelectorAll('a[data-entityformid="23b2f863-28e5-ee11-904c-000d3a8714d9"]');
                    candidateNameLinks.forEach(function(link) {
                        // Perform the link update
                        updateLinkHref(link);
                    });
                }
            });
        });
        // Function to update the link href
        function updateLinkHref(link) {
            // Navigate up to the parent 'new_candidateavailability' entity
            var candidateAvailability = link.closest('[data-entity="new_candidateavailability"]');
            if (candidateAvailability) {
                // Get the related 'new_candidateid' element
                var candidateIdElement = candidateAvailability.querySelector('[data-attribute="new_candidateid"]');
                if (candidateIdElement) {
                    // Extract the Id from the 'data-value' attribute
                    var dataValue = JSON.parse(candidateIdElement.getAttribute('data-value'));
                    if (dataValue && dataValue.Id) {
                        // Update the 'href' attribute of the link
                        link.href = link.href.replace(/(id=)[^\&]+/, '$1' + dataValue.Id);
                        console.log(`Updated link for candidate ID: ${dataValue.Id}`);
                    }
                }
            }
        }
        // Configuration of the observer (which mutations to observe)
        var config = { attributes: false, childList: true, subtree: true };
        // Start observing the target node for configured mutations
        observer.observe(targetNode, config);

    </script>
</div>"
}
